  "ref-ag-doc-activated": "Activado",
  "ref-ag-s1-title": "1. Partes y objeto",
  "ref-ag-s1-body": "Este contrato establece la cooperación entre la empresa que opera esta plataforma y usted como socio referente: usted presenta empresas cliente y oportunidades de negocio, y percibe una comisión por los negocios cerrados con las empresas que refiere.",
  "ref-ag-s2-title": "2. Su papel como socio referente",
  "ref-ag-s2-l1": "Presenta empresas cliente y oportunidades de negocio que usted representa o con las que tiene una relación real.",
  "ref-ag-s2-l2": "Confirma que está facultado para presentar estas empresas y que al hacerlo no incumple ninguna obligación frente a terceros.",
  "ref-ag-s2-l3": "La empresa que presenta queda registrada como su referido: los negocios cerrados con ella generan su comisión según las condiciones siguientes.",
  "ref-ag-s3-title": "3. Comisión",
  "ref-ag-s3-body": "Por los negocios cerrados con las empresas que refiere, usted percibe una comisión conforme a las siguientes condiciones:",
  "ref-ag-s4-title": "4. Condiciones de pago",
  "ref-ag-s4-body": "La comisión se hace exigible cuando el negocio referido se confirma como completado, se han aportado todos los documentos requeridos y la comisión ha sido aprobada. Los pagos se efectúan a la cuenta bancaria que usted designe en Datos de pago.",
  "ref-ag-s5-title": "5. Confidencialidad",
  "ref-ag-s5-body": "Las condiciones de este contrato, la identidad de las empresas referidas y toda la información comercial intercambiada son confidenciales y no pueden divulgarse a terceros.",
  "ref-ag-s6-title": "6. Duración y modificaciones",
  "ref-ag-s6-body": "El contrato rige desde su aceptación hasta su terminación por escrito. Cuando las condiciones cambien, se emitirá una nueva versión y se requerirá su nueva aceptación; su aceptación anterior queda registrada.",
  "ref-ag-custom-title": "Condiciones especiales",
