  "refa-cancel-body": "El registro se marcará como cancelado y seguirá visible para el socio como cancelado. Esto no se puede deshacer (deberá crearse un nuevo registro en su lugar).",
  "refa-ag-dialog-title": "Contrato de referidos",
  "refa-ag-dialog-desc": "Defina las condiciones de la comisión que firma el socio. Actívelo para que sea visible en su portal a efectos de firma.",
  "refa-ag-currency": "Moneda de la comisión",
  "refa-ag-conditions-ph": "Cláusulas especiales que se añaden al texto estándar del contrato (opcional)",
  "refa-ag-resign-note": "Este contrato ya está firmado. Reactivarlo con condiciones modificadas incrementa la versión y el socio deberá firmarlo de nuevo; la aceptación anterior queda registrada.",
