  "refa-ag-reactivate": "Guardar y reactivar (nueva versión)",
  "refa-ag-activated-toast": "Contrato activado — se notificó al socio para que lo firme.",
  "refa-ag-saved-toast": "Contrato guardado.",
  "misc-refresh": "Actualizar",
  "marketplace-kyc-verified": "KYC verificado",
  "marketplace-kyc-not-verified": "KYC sin verificar",
  "marketplace-dd-banner-title": "Comercie con seguridad — haga su propia debida diligencia",
  "marketplace-dd-banner-short": "VELOS es un punto de encuentro neutral que conecta compradores y vendedores. No somos parte de ninguna transacción, no manejamos mercancías ni fondos, y no asumimos responsabilidad por los negocios cerrados entre miembros.",
  "marketplace-dd-banner-full": "Antes de comprometerse: verifique el registro y la reputación de la contraparte, confirme licencias y certificados, exija un pago seguro (depósito en garantía o carta de crédito) y asegúrese de que la operación cumple las leyes que a usted le aplican.",
  "marketplace-dd-open-safety": "Guía de seguridad y cumplimiento",
  "marketplace-dd-show-more": "Mostrar más",
  "marketplace-dd-show-less": "Mostrar menos",
  "marketplace-dd-panel-title": "Seguridad y cumplimiento",
  "marketplace-dd-panel-subtitle": "Orientación práctica de debida diligencia que todo miembro del marketplace debería seguir antes de enviar dinero o mercancías.",
  "marketplace-dd-panel-liability": "VELOS únicamente facilita contactos y herramientas. No somos parte de ningún contrato, no custodiamos ni movemos mercancías ni fondos, no certificamos la legalidad de ninguna publicación y no asumimos responsabilidad por pérdida alguna derivada de una transacción entre miembros. Realice siempre su propia debida diligencia y sus propias comprobaciones de cumplimiento.",
  "marketplace-dd-s1-title": "1. Verifique a la contraparte",
  "marketplace-dd-s1-body": "Compruebe el número de registro de la empresa, el estado de IVA/EORI y la dirección física en los registros oficiales. En VELOS, prefiera socios con la insignia de KYC verificado — su identidad y sus documentos han sido revisados — y lea las reseñas de negocios anteriores. Una llamada y un recorrido por video de las instalaciones son un seguro barato.",
  "marketplace-dd-s2-title": "2. Asegure el pago",
  "marketplace-dd-s2-body": "Use un depósito en garantía (escrow) o una carta de crédito irrevocable con contrapartes nuevas; VELOS admite ambos. Evite transferencias de efectivo por adelantado a cuentas desconocidas y nunca pague a cuentas bancarias personales. Ajuste el calendario de pagos a los hitos de entrega para que ningún importe elevado quede en riesgo en un solo momento.",
  "marketplace-dd-s3-title": "3. Verifique la mercancía",
  "marketplace-dd-s3-body": "Solicite certificados de análisis, especificaciones de calidad y, cuando corresponda, documentos de origen antes de contratar. Use la inspección previa al embarque (SGS, Bureau Veritas o un agente de confianza) y conserve el derecho a rechazar la mercancía que no cumpla las especificaciones acordadas.",
  "marketplace-dd-s4-title": "4. Póngalo por escrito",
  "marketplace-dd-s4-body": "Firme un contrato de compraventa en regla: especificación del producto, Incoterms 2020, calendario de entrega, condiciones de pago, derechos de inspección, resolución de disputas y ley aplicable. Las plantillas de documentos de VELOS y el historial de negociación pueden respaldarlo, pero no sustituyen su propia revisión legal.",
  "marketplace-dd-s5-title": "5. Respete las normas de cumplimiento",
  "marketplace-dd-s5-body": "Las listas de sanciones (UN, EU, OFAC), los controles de exportación, las mercancías de doble uso, las obligaciones AML/KYC y las normas aduaneras le aplican a usted y a su empresa. Es su responsabilidad — no la de VELOS — asegurarse de que una operación prevista sea legal para ambas partes.",
  "marketplace-dd-s6-title": "6. Reporte actividad sospechosa",
  "marketplace-dd-s6-body": "Si una publicación parece fraudulenta, engañosa o prohibida, repórtela con el botón Reportar de la publicación. Nuestro equipo revisa cada reporte. Si un negocio ya salió mal, contacte de inmediato a su banco e involucre a las autoridades de su jurisdicción — VELOS puede apoyar las investigaciones con los datos que conserva lícitamente.",
  "marketplace-locked-tier-title": "La comunicación está bloqueada en su nivel",
  "marketplace-locked-tier-body": "Todos pueden explorar este marketplace, pero publicar, responder, negociar y pujar requieren el nivel Standard o superior. Mejore el nivel de su portal para desbloquear la comunicación.",
  "marketplace-locked-tier-body-respond": "Responder a esta publicación requiere el nivel Standard o superior. Mejore el nivel de su portal para enviar ofertas.",
  "marketplace-locked-tier-body-negotiate": "Enviar mensajes u ofertas requiere el nivel Standard o superior. Mejore el nivel de su portal para continuar negociando.",
  "marketplace-locked-tier-body-bid": "Hacer pujas requiere el nivel Standard o superior. Mejore el nivel de su portal para pujar en subastas.",
  "marketplace-locked-tier-body-qa": "Hacer o responder preguntas requiere el nivel Standard o superior. Mejore el nivel de su portal para unirse a la discusión.",
  "marketplace-locked-kyc-title": "Se requiere verificación KYC",
  "marketplace-locked-kyc-body": "Para comunicarse en el marketplace, su revisión KYC debe estar totalmente aprobada — identidad, empresa y documentos bancarios verificados. Complete o espere su revisión KYC para desbloquear publicar, responder y pujar.",
  "marketplace-locked-kyc-body-respond": "Su revisión KYC debe estar totalmente aprobada antes de poder responder a publicaciones. Complete o espere su revisión KYC.",
  "marketplace-locked-kyc-body-negotiate": "Su revisión KYC debe estar totalmente aprobada antes de poder enviar mensajes u ofertas. Complete o espere su revisión KYC.",
  "marketplace-locked-kyc-body-bid": "Su revisión KYC debe estar totalmente aprobada antes de poder hacer pujas. Complete o espere su revisión KYC.",
  "marketplace-locked-kyc-body-qa": "Su revisión KYC debe estar totalmente aprobada antes de poder hacer o responder preguntas. Complete o espere su revisión KYC.",
  "marketplace-locked-upgrade-cta": "Solicitar mejora de nivel",
  "marketplace-locked-kyc-cta": "Ir a Verificación KYC",
  "marketplace-dd-form-note": "VELOS conecta a las partes comerciales pero no es parte de su negocio — verifique a la contraparte, acuerde un pago seguro (depósito en garantía/carta de crédito) y ponga las condiciones por escrito antes de comprometerse.",
